            "admin panel is still Persian.\n"
            "Each user's language is stored separately — on one bot, "
            "everyone sees their own.\n\n"
            "<b>📬 Daily summary</b>\n"
            "Turn on «👤 Account → 📬 Daily summary» to get a short message "
            "each morning: how many posts went out yesterday, how many "
            "errors, what is waiting for approval, and whether any job "
            "stopped.\n"
            "<i>On a day when nothing notable happened, no message "
            "arrives.</i>"
