            "4. Karta raqami koʻrsatiladi — summani oʻtkazing\n"
            "5. <b>Chek rasmini</b> oʻsha sahifada botga yuboring\n"
            "6. Admin tasdiqlagan zahoti tarif oʻsha lahzada ishga tushadi "
            "va sizga xabar beriladi\n\n"
            "<b>🎟 Chegirma kodi</b>\n"
            "Sotib olish sahifasida «🎟 Chegirma kodim bor»ni bosib kodni "
