            "qoʻshiladi — qolgan kunlaringiz yoʻqolmaydi.\n\n"
            "<b>⬆️ Yuqoriroq tarifga oʻtish</b>\n"
            "<b>Qimmatroq</b> tarif olsangiz, hozirgi tarifingizning "
