            "yechiladi va obuna uzaytiriladi.\n"
            "<i>Standart holda oʻchiq va sizning ruxsatingizsiz hech nima "
            "yechilmaydi. Mablagʻ yetmasa ham hech nima yechilmaydi, faqat "
            "xabar beriladi.</i>\n\n"
            "<b>🎁 Sovgʻa kodi</b>\n"
            "Sovgʻa yoki oldindan sotuv kodingiz boʻlsa: «👛 Hamyon va "
