            "«👛 Hamyon va takliflar» → «🧾 Hisob-fakturalar» xaridlaringiz "
            "tarixini har bir chegirma tafsiloti bilan koʻrsatadi.\n\n"
            "<b>Tugash eslatmalari</b>\n"
            "Obuna tugashiga 3 kun va 1 kun qolganda eslatiladi.\n\n"
            "<b>Tugagandan keyin nima boʻladi?</b>\n"
            "Avtomatik nusxalash vazifalari toʻxtaydi, lekin "
            "<b>sozlamalaringiz oʻchmaydi</b>. Uzaytirsangiz hammasi joyiga "
            "qaytadi."
