            "нажмите «Выбрать из моих чатов».\n\n"
            "<b>Посты приходят с меткой «Переслано от…»?</b>\n"
            "Нет — по умолчанию они копируются без всякого следа "
            "источника. Если метка нужна, смените режим в «⚙️ Отправка и "
            "трафик».\n\n"
            "<b>Фото и видео тоже копируются?</b>\n"
            "Да — текст, фото, видео, GIF, музыка, голосовые, файлы, "
