            "покупки кредитов и повышения тарифа.\n\n"
            "<b>Можно копировать из нескольких каналов в несколько?</b>\n"
            "Да. Создайте по задаче на каждый исходный канал и добавьте в "
            "каждую столько получателей, сколько позволяет тариф.\n\n"
            "<b>Бот пишет «на обслуживании» — это как?</b>\n"
