            "задачи копирования всё это время работают</b>, ничего не "
            "теряется; подождите и отправьте /start снова.\n\n"
            "<b>Почему вы спросили, отчего я не продлил?</b>\n"
            "Потому что лучший способ стать лучше — услышать того, кто не "
            "остался. Отвечать необязательно, это одно нажатие, и на ваш "
            "аккаунт это никак не влияет.\n\n"
            "<b>Мои данные в безопасности?</b>\n"
            "Сеанс хранится зашифрованным, пароль не сохраняется никогда. "
            "«🔒 PIN-код» позволяет закрыть доступ к важным действиям."
