            "<b>Filigran metnine emoji koyabilir miyim?</b>\n"
            "Evet, <b>renkli</b> emoji desteklenir — tek başına ya da "
            "metnin yanında (<code>🔥 @MyChannel</code> gibi). Sunucuda "
            "emoji yazı tipi yoksa bot bunu hemen söyler, siz de emojiyi "
            "çıkartma olarak gönderebilirsiniz.\n\n"
            "<b>Uygulanmadan önce nasıl görüneceğini görebilir miyim?</b>\n"
            "Evet. Filigran menüsünde «🎨 Önizlemeyle oluştur»a dokunup "
            "istediğinizi gönderin — metin, emoji, fotoğraf ya da "
            "çıkartma. Bot kaynak kanaldan gerçek bir fotoğraf üzerine 6 "
            "değişik biçim (farklı konum, boyut ve saydamlık) kurar ve "
